const body = $json.body ?? $json;
const lista = Array.isArray(body.shipments) ? body.shipments : [];
const vistos = new Set();
const validos = [];
const invalidos = [];
for (const s of lista) {
  const ship = String(s.ship ?? '').trim();
  const importe = Number(s.importe);
  if (!/^[0-9]{1,15}$/.test(ship) || !Number.isFinite(importe)) { invalidos.push(s); continue; }
  if (vistos.has(ship)) continue;
  vistos.add(ship);
  validos.push({ ship, importe: Math.round(importe * 100) / 100, lineas: Number(s.lineas) || null });
}
if (validos.length === 0) {
  throw new Error('No llegan shipments válidos en el cuerpo (se espera {shipments:[{ship, importe, lineas}]})');
}
const valores = validos.map(v => "('" + v.ship + "')").join(',');
const query = "SELECT s.ship AS Shipment, p.cdbNumeroPedido AS Pedido, p.cdbImporte AS Importe FROM (VALUES " + valores + ") AS s(ship) LEFT JOIN [T_DIANIA].[dbo].[tdbPedidos] p ON LTRIM(RTRIM(p.cdbNumPedCliente)) = s.ship ORDER BY s.ship, p.cdbNumeroPedido";
return [{ json: { query, shipments: validos, invalidos, totalPdfDeclarado: body.total_pdf ?? null } }];

const prep = $('Preparar consulta').first().json;
const filasSql = $input.all().map(i => i.json);
const r2 = n => Math.round(n * 100) / 100;
const eur = n => (n === null || n === undefined) ? '' : n.toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const porShip = {};
for (const f of filasSql) {
  const k = String(f.Shipment);
  (porShip[k] = porShip[k] || []).push(f);
}

const filas = prep.shipments.map(s => {
  const pedidos = (porShip[s.ship] || []).filter(f => f.Pedido !== null && f.Pedido !== undefined);
  const nuestro = pedidos.length ? r2(pedidos.reduce((a, f) => a + (Number(f.Importe) || 0), 0)) : null;
  const dif = nuestro === null ? null : r2(s.importe - nuestro);
  let estado;
  if (pedidos.length === 0) estado = 'SIN PEDIDO NUESTRO';
  else if (Math.abs(dif) > 0.009) estado = 'DIFIERE';
  else estado = 'OK';
  if (pedidos.length > 1) estado += ' (varios pedidos)';
  return {
    pedido: pedidos.map(f => f.Pedido).join(', '),
    pedido_cliente: s.ship,
    importe_nuestro: nuestro,
    importe_cliente: s.importe,
    diferencia: dif,
    estado,
    lineas_pdf: s.lineas
  };
});

// Primero lo que requiere atención
const orden = { 'SIN PEDIDO NUESTRO': 0, 'DIFIERE': 1, 'OK': 2 };
const rango = e => orden[e.split(' (')[0]] ?? 3;
filas.sort((a, b) => rango(a.estado) - rango(b.estado) || a.pedido_cliente.localeCompare(b.pedido_cliente));

const cuenta = e => filas.filter(f => f.estado.startsWith(e)).length;
const totCliente = r2(filas.reduce((a, f) => a + f.importe_cliente, 0));
const totNuestro = r2(filas.reduce((a, f) => a + (f.importe_nuestro ?? 0), 0));
const resumen = {
  shipments: filas.length,
  ok: cuenta('OK'),
  difieren: cuenta('DIFIERE'),
  sin_pedido: cuenta('SIN PEDIDO'),
  total_cliente: totCliente,
  total_nuestro: totNuestro,
  diferencia_total: r2(totCliente - totNuestro),
  total_pdf_declarado: prep.totalPdfDeclarado,
  invalidos: prep.invalidos.length
};

let md = '| Pedido (nuestro) | Pedido cliente (shipment) | Importe nuestro | Importe cliente (agrupado) | Diferencia | Estado |\n|---|---|---:|---:|---:|---|\n';
for (const f of filas) {
  md += '| ' + (f.pedido || '—') + ' | ' + f.pedido_cliente + ' | ' + (f.importe_nuestro === null ? '—' : eur(f.importe_nuestro)) + ' | ' + eur(f.importe_cliente) + ' | ' + (f.diferencia === null ? '—' : eur(f.diferencia)) + ' | ' + f.estado + ' |\n';
}
md += '| **TOTAL** | ' + filas.length + ' shipments | **' + eur(totNuestro) + '** | **' + eur(totCliente) + '** | **' + eur(resumen.diferencia_total) + '** | ' + resumen.ok + ' OK / ' + resumen.difieren + ' difieren / ' + resumen.sin_pedido + ' sin pedido |\n';

return [{ json: { resumen, filas, markdown: md } }];

